export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

/**
 * People who have taken part in an issue: its author, its current assignee,
 * and authors of comments that have not been deleted. Someone removed from
 * the organization is left out, and each user appears at most once. Anyone
 * who may read the thread (viewers included) may ask.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthorIds = await commentRepo.listCommentAuthorIds(
    orgId,
    issueId,
  );
  const candidateIds = new Set<UserId>([
    issue.authorId,
    ...commentAuthorIds,
  ]);
  if (issue.assigneeId !== null) {
    candidateIds.add(issue.assigneeId);
  }

  const memberships = await Promise.all(
    [...candidateIds].map(async (userId) => {
      const member = await memberRepo.findMember(orgId, userId);
      return member !== null && member.status === "active" ? userId : null;
    }),
  );

  return memberships.filter((userId): userId is UserId => userId !== null);
}

