import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { issueParticipantsSchema } from "@/schemas/comment";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as commentService from "@/server/services/comment-service";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("participants-north");
  acme = await createTenant("participants-acme");
});

afterAll(() => {
  cleanup();
});

describe("issue participants", () => {
  it("validates org and issue ids like the other comment schemas", () => {
    expect(
      issueParticipantsSchema.safeParse({
        orgId: north.org.id,
        issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
      }).success,
    ).toBe(true);
    expect(
      issueParticipantsSchema.safeParse({
        orgId: "nope",
        issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
      }).success,
    ).toBe(false);
  });

  it("returns the author, assignee, and live comment authors once each", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, {
        title: "Participants",
        assigneeId: north.userIds.admin,
      }),
    );

    await commentService.createComment(north.actors.viewer, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "viewer note",
      parentId: null,
      mentionedUserIds: [],
    });
    const parent = await commentService.createComment(north.actors.owner, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "owner note",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(north.actors.admin, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "reply from assignee",
      parentId: parent.id,
      mentionedUserIds: [],
    });
    await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "author comments too",
      parentId: null,
      mentionedUserIds: [],
    });

    const ids = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      issue.id,
    );

    expect(new Set(ids)).toEqual(
      new Set([
        north.userIds.member,
        north.userIds.admin,
        north.userIds.viewer,
        north.userIds.owner,
      ]),
    );
    expect(ids).toHaveLength(4);
  });

  it("drops authors whose only comments were deleted, and removed members", async () => {
    const issue = await issueService.createIssue(
      north.actors.owner,
      issueInput(north.org.id, north.project.id, {
        title: "Deleted and removed",
        assigneeId: north.userIds.viewer,
      }),
    );

    const doomed = await commentService.createComment(north.actors.admin, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "will vanish",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(north.actors.admin, {
      orgId: north.org.id,
      commentId: doomed.id,
    });

    const kept = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "stays",
      parentId: null,
      mentionedUserIds: [],
    });
    const alsoDoomed = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "member also deleted one",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentRepo.archiveComment(north.org.id, alsoDoomed.id);

    const viewerMember = await memberRepo.findMember(
      north.org.id,
      north.userIds.viewer,
    );
    expect(viewerMember).not.toBeNull();
    await memberService.removeMember(north.actors.owner, {
      orgId: north.org.id,
      memberId: viewerMember!.id,
    });

    const authors = await commentRepo.listCommentAuthorIds(north.org.id, issue.id);
    expect(authors).toEqual([north.userIds.member]);
    expect(authors).not.toContain(north.userIds.admin);

    const ids = await commentService.getIssueParticipants(
      north.actors.member,
      north.org.id,
      issue.id,
    );

    expect(new Set(ids)).toEqual(
      new Set([north.userIds.owner, north.userIds.member]),
    );
    expect(kept.id).toBeTruthy();
  });

  it("rejects another organization and a missing issue", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Scoped issue" }),
    );

    await expect(
      commentService.getIssueParticipants(
        acme.actors.owner,
        north.org.id,
        issue.id,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      commentService.getIssueParticipants(
        north.actors.viewer,
        north.org.id,
        acme.project.id as never,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("does not let a cross-tenant caller through even when the role could read", async () => {
    await expect(
      commentService.getIssueParticipants(
        { ...north.actors.viewer, orgId: acme.org.id },
        north.org.id,
        "01HZZZSSSSSSSSSSSSSSSSSSSS" as never,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("denies callers who cannot read the thread", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Denied" }),
    );

    await expect(
      commentService.getIssueParticipants(
        { ...north.actors.viewer, role: "guest" as never },
        north.org.id,
        issue.id,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
