        orgId: "nope",
        issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
      }).success,
    ).toBe(false);
  });

  it("returns the author, assignee, and live comment authors once each", async () => {
    const issue = await issueService.createIssue(
