      mentionedUserIds: [],
    });
    const parent = await commentService.createComment(north.actors.owner, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "owner note",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(north.actors.admin, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "reply from assignee",
      parentId: parent.id,
      mentionedUserIds: [],
    });
    await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "author comments too",
      parentId: null,
      mentionedUserIds: [],
    });

    const ids = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      issue.id,
