      orgId: north.org.id,
      issueId: issue.id,
      body: "stays",
      parentId: null,
      mentionedUserIds: [],
    });
    const alsoDoomed = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: issue.id,
      body: "member also deleted one",
      parentId: null,
