      north.actors.member,
      north.org.id,
      issue.id,
    );

    expect(new Set(ids)).toEqual(
      new Set([north.userIds.owner, north.userIds.member]),
    );
    expect(kept.id).toBeTruthy();
  });

  it("rejects another organization and a missing issue", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Scoped issue" }),
    );

    await expect(
      commentService.getIssueParticipants(
        acme.actors.owner,
        north.org.id,
        issue.id,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      commentService.getIssueParticipants(
        north.actors.viewer,
        north.org.id,
        acme.project.id as never,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("does not let a cross-tenant caller through even when the role could read", async () => {
    await expect(
      commentService.getIssueParticipants(
        { ...north.actors.viewer, orgId: acme.org.id },
        north.org.id,
        "01HZZZSSSSSSSSSSSSSSSSSSSS" as never,
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

